import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Central Feedback System","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Central Feedback System | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/central-feedback-system"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Central Feedback System | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/central-feedback-system"}]]},"headers":[],"relativePath":"developer-guide/central-feedback-system.md","filePath":"developer-guide/central-feedback-system.md","lastUpdated":1788225865000}'),i={name:"developer-guide/central-feedback-system.md"};function d(r,e,s,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="central-feedback-system" tabindex="-1">Central Feedback System <a class="header-anchor" href="#central-feedback-system" aria-label="Permalink to &quot;Central Feedback System&quot;">​</a></h1><p>Architecture for EloSync product feedback: <strong>submitted from the Tenant Application</strong>, <strong>managed in the Central Application</strong>.</p><blockquote><p><strong>Status: Implemented</strong></p><p>Shipped with Backend <a href="https://github.com/DiligentCreators/EloSync-Backend/pull/93" target="_blank" rel="noreferrer">#93</a> and Frontend <a href="https://github.com/DiligentCreators/EloSync-Frontend/pull/88" target="_blank" rel="noreferrer">#88</a>. Architecture stays aligned with Sanctum dual-guard, Spatie RBAC, single-DB tenancy, Central React SPA, <code>FileUploadService</code>, and <code>PlatformAuditService</code>. User-facing flows: <a href="/user-guide/feedback">Give Feedback</a>.</p></blockquote><p>Related: <a href="/product/founding-beta">Founding Beta</a> · <a href="/developer-guide/authentication">Authentication</a> · <a href="/developer-guide/object-storage">Object Storage</a> · <a href="/user-guide/admin-ui">Admin UI</a> · <a href="/getting-started/platform-freeze">Platform Freeze</a></p><hr><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ol><li>Give tenant users a lightweight way to report bugs, UX issues, feature requests, performance problems, and integration gaps.</li><li>Give the EloSync operator team a Central inbox for triage, priority, public replies, and private notes.</li><li>Enforce <strong>tenant isolation</strong> and <strong>internal-note secrecy</strong> in the API, not only in the UI.</li><li>Keep feedback as a <strong>platform concern</strong> — not a licensed tenant Marketplace module and not a second support-ticket product.</li></ol><hr><h2 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────┐     Tenant Sanctum      ┌─────────────────────┐</span></span>
<span class="line"><span>│  Tenant SPA        │ ─────────────────────► │  /api/tenant/v1/     │</span></span>
<span class="line"><span>│  Give Feedback UI  │                         │  feedback*           │</span></span>
<span class="line"><span>└────────────────────┘                         └──────────┬──────────┘</span></span>
<span class="line"><span>                                                          │</span></span>
<span class="line"><span>                                                          ▼</span></span>
<span class="line"><span>                                               ┌─────────────────────┐</span></span>
<span class="line"><span>                                               │  Central DB models  │</span></span>
<span class="line"><span>                                               │  (tenant_id linked) │</span></span>
<span class="line"><span>                                               └──────────┬──────────┘</span></span>
<span class="line"><span>                                                          │</span></span>
<span class="line"><span>┌────────────────────┐     Central Sanctum     ┌──────────▼──────────┐</span></span>
<span class="line"><span>│  Central SPA       │ ◄────────────────────── │  /api/central/v1/   │</span></span>
<span class="line"><span>│  Feedback inbox    │                         │  feedback*           │</span></span>
<span class="line"><span>└────────────────────┘                         └─────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Concern</th><th>Home</th></tr></thead><tbody><tr><td>Ticket storage</td><td>Central-owned tables with <code>tenant_id</code> + submitting <code>user_id</code></td></tr><tr><td>Tenant submit / view own</td><td>Tenant API + tenant shell dialog</td></tr><tr><td>Operator triage</td><td>Central API + Central nav (<code>feedback.*</code> permissions)</td></tr><tr><td>Website Founding Beta applications</td><td>Separate public intake (<code>/api/central/v1/public/beta-applications</code>) — applications, not in-app feedback tickets</td></tr></tbody></table><p><strong>Implemented:</strong> in-app feedback APIs + Tenant Give Feedback dialog + Central Feedback inbox.<br><strong>Implemented:</strong> public beta application intake used by <code>elosync.com/beta/</code> + Central Beta Applications triage.</p><hr><h2 id="data-ownership" tabindex="-1">Data ownership <a class="header-anchor" href="#data-ownership" aria-label="Permalink to &quot;Data ownership&quot;">​</a></h2><ul><li>Feedback rows are <strong>platform records</strong> visible to authorized Central users.</li><li>Each row references the originating <strong>tenant</strong> and <strong>tenant user</strong>.</li><li>Tenants never receive cross-tenant lists.</li><li>Central users operate outside <code>TenantScope</code> (same pattern as other Central APIs).</li></ul><hr><h2 id="tenant-isolation" tabindex="-1">Tenant isolation <a class="header-anchor" href="#tenant-isolation" aria-label="Permalink to &quot;Tenant isolation&quot;">​</a></h2><p>Server-side rules (non-negotiable):</p><table tabindex="0"><thead><tr><th>Actor</th><th>Allowed</th><th>Forbidden</th></tr></thead><tbody><tr><td>Tenant user</td><td>Create feedback for own tenant; list/show own submissions (or policy-scoped tenant submissions if explicitly designed); post <strong>public</strong> comments on own items</td><td>See other tenants; see internal notes; set internal priority / Central-only statuses beyond any allowed public fields; download another tenant&#39;s attachments</td></tr><tr><td>Central user with <code>feedback.*</code></td><td>List/filter all; update status/priority; internal notes; public replies</td><td>N/A</td></tr></tbody></table><p>Isolation is enforced with policies + query scoping on tenant routes — <strong>not</strong> frontend filtering alone.</p><hr><h2 id="central-visibility" tabindex="-1">Central visibility <a class="header-anchor" href="#central-visibility" aria-label="Permalink to &quot;Central visibility&quot;">​</a></h2><p>Central detail view should include:</p><ul><li>Feedback identity (<code>FB-######</code> public number + UUID)</li><li>Type, title, description, severity/impact (if collected)</li><li>Status, priority</li><li>Tenant / workspace context</li><li>Submitter</li><li>Module + route / page context</li><li>Browser / device metadata when captured</li><li>Attachments</li><li>Activity timeline (status changes, public comments, internal notes)</li></ul><hr><h2 id="api-flow" tabindex="-1">API flow <a class="header-anchor" href="#api-flow" aria-label="Permalink to &quot;API flow&quot;">​</a></h2><p>Routes live in <code>routes/tenant/v1.php</code> and <code>routes/central/v1.php</code>. Feedback is a <strong>platform</strong> concern (no <code>module:feedback</code> middleware).</p><h3 id="tenant-auth-tenant-api" tabindex="-1">Tenant (auth: <code>tenant-api</code>) <a class="header-anchor" href="#tenant-auth-tenant-api" aria-label="Permalink to &quot;Tenant (auth: \`tenant-api\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/tenant/v1/feedback</code></td><td>Create feedback (JSON, or multipart when an attachment is present). <code>module_slug</code> is <strong>required</strong> (<code>string</code>, <code>max:100</code>) — catalog slug or a short free-text area when the reporter chose Other in the SPA</td></tr><tr><td><code>GET</code></td><td><code>/api/tenant/v1/feedback</code></td><td>List own submissions</td></tr><tr><td><code>GET</code></td><td><code>/api/tenant/v1/feedback/{feedback}</code></td><td>Show (public fields + public comments + public activity timeline; never priority or internal notes)</td></tr><tr><td><code>POST</code></td><td><code>/api/tenant/v1/feedback/{feedback}/comments</code></td><td>Public comment</td></tr><tr><td><code>GET</code></td><td><code>/api/tenant/v1/feedback/attachments/{attachment}/download</code></td><td>Download own attachment</td></tr></tbody></table><p>Tenant SPA detail: <code>/#/feedback/{uuid}</code> (reporter only). Email status/public-reply CTAs deep-link to that page. The Give Feedback dialog <strong>My submissions</strong> tab still lists recent items and links into the detail page.</p><h3 id="central-auth-central-api" tabindex="-1">Central (auth: <code>central-api</code>) <a class="header-anchor" href="#central-auth-central-api" aria-label="Permalink to &quot;Central (auth: \`central-api\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/central/v1/feedback</code></td><td>List + filters + pagination</td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/feedback/stats</code></td><td>Lightweight triage summary</td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/feedback/{feedback}</code></td><td>Full detail including internal notes</td></tr><tr><td><code>PATCH</code></td><td><code>/api/central/v1/feedback/{feedback}</code></td><td>Status, priority, module linkage fields</td></tr><tr><td><code>POST</code></td><td><code>/api/central/v1/feedback/{feedback}/comments</code></td><td>Public reply or internal note (<code>is_internal</code> boolean)</td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/feedback/attachments/{attachment}/download</code></td><td>Authorized download</td></tr></tbody></table><h3 id="beta-applications" tabindex="-1">Beta applications <a class="header-anchor" href="#beta-applications" aria-label="Permalink to &quot;Beta applications&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth / purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/central/v1/public/beta-applications</code></td><td>Public + throttle; marketing application</td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/public/beta-invites/{token}</code></td><td>Public + throttle; preview validity, expiry, activation, and applicant details for registration</td></tr><tr><td><code>POST</code></td><td><code>/api/central/v1/public/beta-invites/resend</code></td><td>Public + throttle; body <code>{ &quot;email&quot;: &quot;…&quot; }</code>; rotates an eligible accepted invite and always returns a non-enumerating message</td></tr><tr><td><code>POST</code></td><td><code>/api/central/v1/public/register-workspace</code></td><td>Public + throttle; optional <code>invite_token</code> bypasses disabled open registration after server-side token, status, expiry, activation, and email checks</td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/beta-applications</code></td><td><code>beta-applications.list</code></td></tr><tr><td><code>GET</code></td><td><code>/api/central/v1/beta-applications/{beta_application}</code></td><td><code>beta-applications.read</code></td></tr><tr><td><code>PATCH</code></td><td><code>/api/central/v1/beta-applications/{beta_application}</code></td><td><code>beta-applications.update</code></td></tr><tr><td><code>POST</code></td><td><code>/api/central/v1/beta-applications/{beta_application}/invite</code></td><td><code>beta-applications.update</code>; accepts the application, rotates the hashed token, queues mail, and returns <code>invite_url</code> for copy-link UI</td></tr></tbody></table><p>Invite tokens are stored only as SHA-256 hashes. Registration atomically consumes the invite by linking the application to the new tenant, setting <code>activated_at</code>, and clearing the token.</p><p>Envelope: existing <code>ApiResponseService</code> <code>{ status, message, data, meta }</code>.</p><hr><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Guard</th><th>Model</th></tr></thead><tbody><tr><td>Tenant feedback</td><td><code>tenant-api</code></td><td><code>User</code></td></tr><tr><td>Central feedback</td><td><code>central-api</code></td><td><code>CentralUser</code></td></tr><tr><td>Website beta applications</td><td>Public + throttle (no tenant session)</td><td>Stored as application rows for Central review</td></tr></tbody></table><p>No new auth system. Sanctum + existing SPA cookie/token flows only.</p><hr><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><p>Central permissions in <code>config/central-permissions.php</code> (synced via migration / seeders):</p><ul><li><code>feedback.list</code>, <code>feedback.read</code>, <code>feedback.update</code>, <code>feedback.comment</code>, <code>feedback.stats</code></li><li><code>beta-applications.list</code>, <code>beta-applications.read</code>, <code>beta-applications.update</code></li></ul><p>Tenant: <strong>any authenticated workspace user</strong> may submit and list their own feedback. There is no Marketplace module entitlement and no <code>module:feedback</code> license.</p><p>Policies decide attachment download and comment visibility.</p><hr><h2 id="feedback-types" tabindex="-1">Feedback types <a class="header-anchor" href="#feedback-types" aria-label="Permalink to &quot;Feedback types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Intent</th></tr></thead><tbody><tr><td><code>bug</code></td><td>Something is broken</td></tr><tr><td><code>feature_request</code></td><td>Missing capability</td></tr><tr><td><code>ux</code></td><td>Confusing / hard to use</td></tr><tr><td><code>performance</code></td><td>Slow / unreliable</td></tr><tr><td><code>integration</code></td><td>Connector / third-party issue</td></tr><tr><td><code>other</code></td><td>General product feedback</td></tr></tbody></table><hr><h2 id="status-lifecycle" tabindex="-1">Status lifecycle <a class="header-anchor" href="#status-lifecycle" aria-label="Permalink to &quot;Status lifecycle&quot;">​</a></h2><p>Recommended statuses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>new → triaged → planned → in_progress → resolved → closed</span></span></code></pre></div><p>Also support: <code>duplicate</code>, <code>wont_fix</code>, <code>not_reproducible</code>.</p><p>Only Central (authorized) transitions statuses. Tenant resources may expose a reduced public status label.</p><hr><h2 id="priority" tabindex="-1">Priority <a class="header-anchor" href="#priority" aria-label="Permalink to &quot;Priority&quot;">​</a></h2><p>Internal only: <code>low</code> | <code>medium</code> | <code>high</code> | <code>critical</code>.</p><p>Tenant submitters may optionally send <strong>impact</strong> language; they must not arbitrarily set operator priority unless a future product decision says otherwise.</p><hr><h2 id="attachments-screenshots" tabindex="-1">Attachments / screenshots <a class="header-anchor" href="#attachments-screenshots" aria-label="Permalink to &quot;Attachments / screenshots&quot;">​</a></h2><p><strong>Implemented</strong> reuse:</p><ul><li><code>App\\Services\\Storage\\FileUploadService</code></li><li>Private disk path under the workspace prefix for feedback attachments</li><li>Allowlisted MIME types + max size validation (<code>max:5120</code> KB)</li><li>Authorized download routes (tenant: own item; Central: with permission; SPA uses authenticated blob download, not bare public URLs)</li></ul><p>Do <strong>not</strong> invent a parallel storage stack.</p><hr><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Visibility</th><th>Who can create</th></tr></thead><tbody><tr><td>Public response</td><td>Tenant submitter + Central</td><td>Tenant (on own item) + Central</td></tr><tr><td>Internal note</td><td>Central only</td><td>Central</td></tr></tbody></table><p>API resources for tenant <strong>must omit</strong> internal notes even if a client crafts requests. Tests must prove this.</p><hr><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Reuse existing notification infrastructure — do not build a second bus.</p><table tabindex="0"><thead><tr><th>Event</th><th>Audience</th><th>Channel</th></tr></thead><tbody><tr><td>Critical bug reported</td><td>Operators via System Settings <code>support_email</code></td><td>Mail (<code>CriticalFeedbackReported</code>)</td></tr><tr><td>Status changed (Central triage)</td><td>Submitting tenant user (<code>user_id</code>)</td><td>Mail (<code>FeedbackReporterUpdated</code>, kind <code>status_changed</code>) — delayed ~90s and suppressed if status moved again during debounce; skipped when the reporter is missing/soft-deleted or has no email; priority/module-only updates do not notify</td></tr><tr><td>Public reply from Central</td><td>Submitting tenant user</td><td>Mail (<code>FeedbackReporterUpdated</code>, kind <code>public_reply</code>, immediate) — internal notes never notify</td></tr></tbody></table><p>Reporter mail uses platform branding (same pattern as <code>CriticalFeedbackReported</code>), not tenant Branded chrome. Status/public-reply mail includes a <strong>View feedback</strong> CTA (<code>/#/feedback/{uuid}</code>) that opens the reporter’s dedicated ticket page (history, public comments, attachments). The shell dialog deep link (<code>/#/dashboard?feedback=submissions</code>) still opens <strong>My submissions</strong>. In-app / CRM preference mute channels remain out of scope (transactional platform mail, same as critical-bug operator alerts).</p><hr><h2 id="audit-logging" tabindex="-1">Audit logging <a class="header-anchor" href="#audit-logging" aria-label="Permalink to &quot;Audit logging&quot;">​</a></h2><p>Use <code>PlatformAuditService</code> / <code>activity(&#39;platform&#39;)</code> for Central triage actions (status/priority changes, sensitive access if required). Tenant create events may also be audited consistently with other platform actions.</p><hr><h2 id="identifiers" tabindex="-1">Identifiers <a class="header-anchor" href="#identifiers" aria-label="Permalink to &quot;Identifiers&quot;">​</a></h2><p>Prefer human-readable <strong><code>FB-000001</code></strong> style numbers using Central sequential allocation (same idea as Central invoice numbers / document prefixes), plus UUID for stable public references if needed. Do not expose only auto-increment IDs if that conflicts with broader API norms for new resources.</p><hr><h2 id="retention-privacy" tabindex="-1">Retention &amp; privacy <a class="header-anchor" href="#retention-privacy" aria-label="Permalink to &quot;Retention &amp; privacy&quot;">​</a></h2><ul><li>Feedback may contain PII and screenshots of customer data — treat as sensitive tenant-linked content.</li><li>Retention policy should follow broader platform data retention once defined; until then, do not build open public indexes of feedback.</li><li>Internal notes must never appear in tenant payloads, exports meant for tenants, or marketing surfaces.</li></ul><hr><h2 id="security-checklist-tests-required" tabindex="-1">Security checklist (tests required) <a class="header-anchor" href="#security-checklist-tests-required" aria-label="Permalink to &quot;Security checklist (tests required)&quot;">​</a></h2><p>Pest + SPA unit/e2e coverage ships with the feature and includes:</p><ol><li>Tenant A cannot read Tenant B feedback or attachments</li><li>Tenant cannot read internal notes</li><li>Unauthorized Central user cannot list/manage feedback</li><li>Validation rejects invalid types / oversized files</li><li>Only Central can change status/priority</li><li>Public comments visible; internal notes hidden on tenant show</li><li>Public activity timeline on tenant show includes status/module changes; priority changes never leak</li><li>Critical bugs mail <code>support_email</code> (cache cleared after system-settings seed)</li><li>Frontend: dialog schema + detail page + Playwright shell wiring (<code>test:e2e:feedback</code>) against a stubbed tenant API</li></ol><hr><h2 id="feature-board-parked-—-do-not-build-here" tabindex="-1">Feature Board (parked — do not build here) <a class="header-anchor" href="#feature-board-parked-—-do-not-build-here" aria-label="Permalink to &quot;Feature Board (parked — do not build here)&quot;">​</a></h2><p>Cross-tenant or logged-in <strong>shared ideation</strong> (see what others request, vote, add requirements) is <strong>out of scope</strong> for Give Feedback. Feedback tickets may contain screenshots and customer PII; they stay <strong>reporter-only</strong> on the tenant API.</p><p>When demand is clear, ship a separate <strong>Feature Board</strong> platform surface (sanitized titles/descriptions, no attachment dump by default). Tracked under <a href="/getting-started/product-roadmap#parked-do-not-promise-wait-for-multi-tenant-signal">Product Roadmap → Future Expansion → Parked</a>. Do not open cross-tenant lists on <code>feedback_items</code>.</p><h2 id="future-integrations-do-not-pre-build" tabindex="-1">Future integrations (do not pre-build) <a class="header-anchor" href="#future-integrations-do-not-pre-build" aria-label="Permalink to &quot;Future integrations (do not pre-build)&quot;">​</a></h2><p>Nullable linkage fields only until a real system exists:</p><ul><li>Roadmap item / release id</li><li>External issue tracker id</li><li>Internal development task reference</li></ul><p>Do <strong>not</strong> create a duplicate task management product inside feedback.</p><hr><h2 id="analytics-product-learning-later" tabindex="-1">Analytics / product learning (later) <a class="header-anchor" href="#analytics-product-learning-later" aria-label="Permalink to &quot;Analytics / product learning (later)&quot;">​</a></h2><p>Design aggregates later from stored type/module/tenant/status fields:</p><ul><li>Modules with most bugs vs feature requests</li><li>Most active feedback tenants</li><li>Recurring UX themes</li><li>Multi-tenant critical bugs</li></ul><p>Do not ship a full analytics suite in v1.</p><hr><h2 id="website-beta-applications-vs-in-app-feedback" tabindex="-1">Website beta applications vs in-app feedback <a class="header-anchor" href="#website-beta-applications-vs-in-app-feedback" aria-label="Permalink to &quot;Website beta applications vs in-app feedback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>Purpose</th></tr></thead><tbody><tr><td>Marketing <code>/beta/</code> form</td><td>Qualify founding beta applicants <strong>before</strong> workspace use</td></tr><tr><td>Tenant Give Feedback</td><td>Continuous product learning <strong>after</strong> access</td></tr></tbody></table><p>Keep models/APIs separate so applicant PII and product tickets do not overload one ambiguous table without clear type discrimination.</p><hr><h2 id="documentation-sync-rule" tabindex="-1">Documentation sync rule <a class="header-anchor" href="#documentation-sync-rule" aria-label="Permalink to &quot;Documentation sync rule&quot;">​</a></h2><p>Keep this page synchronized when behavior changes:</p><ol><li>Exact routes, permissions, and UI entry points below stay accurate.</li><li>Update <a href="/product/founding-beta">Founding Beta</a> status table when intake / access model changes.</li><li>Keep <a href="/user-guide/feedback">Give Feedback</a> aligned with shell + Central UX.</li><li>Add dedicated API reference pages under Central / Tenant v1 docs when those catalogs grow a Feedback section.</li><li>Add a changelog delivery note the same day as user- or operator-visible changes.</li></ol>`,107)])])}const b=t(i,[["render",d]]);export{u as __pageData,b as default};
